#!/bin/bash
set -eu
export PYTHONDONTWRITEBYTECODE=1
exec /home/loosqk/.local/share/uv/python/cpython-3.12.13-linux-aarch64-gnu/bin/python3 - <<'PYREMOTE'
import base64,hashlib,importlib.util,json,os,subprocess,time
from pathlib import Path
base=Path('/home/loosqk/robot-checks/position-return-20261010-r1');phase=base/'head-settle-r8'
phase.mkdir(mode=0o700)
source_raw=base64.b64decode('',validate=True)
assert len(source_raw)==9328 and hashlib.sha256(source_raw).hexdigest()=='11b86f6768359bc7f6f0063bd188868b08c8baf164a59d89a62acdb557d7fc5e'
candidate=phase/'head1_outward_observation_r8.py'
with candidate.open('xb') as stream:stream.write(source_raw);stream.flush();os.fsync(stream.fileno())
assert candidate.read_bytes()==source_raw
old_path=base/'position-return-r6/maintenance_bindings_p24_wire_r6.json'
old_raw=old_path.read_bytes();assert hashlib.sha256(old_raw).hexdigest()=='f7649ee42c25494b6238f85606b414be46735aeec66dbda57797400d5b5b299d'
script=base/'software-facts-r1/scripts/run_hardware_maintenance.py'
assert hashlib.sha256(script.read_bytes()).hexdigest()=='d97e0da9b792d048681053054296de66e7f3ef37cf392852784587b51a8b1d41'
spec=importlib.util.spec_from_file_location('wire_r5_prepare_maintenance',script);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
old=m.strict_json(old_raw.decode())
helper=base/'position-return-r6/p24_trial_head1_wire_r6.py'
helper_raw=helper.read_bytes();assert len(helper_raw)==12425 and hashlib.sha256(helper_raw).hexdigest()=='939e590b9e0ef829a465e9b3bc620d14cb114c01f7c2f2d591d3d34db3c47c81'
assert any(r['path']==str(helper) and r['sha256']=='939e590b9e0ef829a465e9b3bc620d14cb114c01f7c2f2d591d3d34db3c47c81' and r['bytes']==12425 for r in old['refs'])
for ref in old['refs']:m.verify_ref(ref)
for side,files in old['protection'].items():
 for name,ref in files.items():m.verify_protection_file(side,name,ref)
assert Path('/proc/sys/kernel/random/boot_id').read_text().strip()==old['host']['boot_id']
for side,ref in old['usb'].items():
 device=Path(ref['device']);assert str(device.resolve())==ref['resolved'] and device.stat().st_rdev==ref['rdev'] and device.stat().st_ino==ref['device_inode'] and device.lstat().st_ino==ref['link_inode']
reference={'path':str(candidate),'sha256':hashlib.sha256(source_raw).hexdigest(),'bytes':len(source_raw)}
binding={**old,'refs':[*old['refs'],reference]}
assert all(binding[k]==old[k] for k in old if k!='refs') and binding['refs'][:-1]==old['refs']
path=phase/'maintenance_bindings_head_settle_r8.json'
with path.open('x') as stream:json.dump(binding,stream,ensure_ascii=False,indent=2);stream.write('\n');stream.flush();os.fsync(stream.fileno())
output=phase/'head1-outward-observation-r8';go=phase/'head1-outward-observation-r8.go.json';record=phase/'head1-outward-observation-launch-r8'
assert not output.exists() and not go.exists() and not record.exists()
argv=['/home/loosqk/.local/share/uv/python/cpython-3.12.13-linux-aarch64-gnu/bin/python3',str(candidate),'--helper',str(helper),'--maintenance',str(script),'--bindings',str(path),'--output',str(output),'--run-id','head1-outward-observation-r8','--artifact-root',str(base)]
default_argv=[argv[0],str(candidate)]
default_start=time.time_ns();defaultchild=subprocess.Popen(default_argv,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE);defout,deferr=defaultchild.communicate();defcode=defaultchild.wait()
defrow={'name':'default-plan-only','argv':default_argv,'pid':defaultchild.pid,'started_ns':default_start,'finished_ns':time.time_ns(),'exit_code':defcode,'wait_returncode':defcode,'reaped':True,'signals_sent':[]}
for suffix,data in [('stdout',defout),('stderr',deferr)]:
 with (phase/('default-plan-only.'+suffix)).open('xb') as stream:stream.write(data);stream.flush();os.fsync(stream.fileno())
 defrow[suffix+'_bytes']=len(data);defrow[suffix+'_sha256']=hashlib.sha256(data).hexdigest()
with (phase/'default-plan-only.receipt.json').open('x') as stream:json.dump(defrow,stream,ensure_ascii=False,indent=2);stream.write('\n')
assert defcode==0 and not deferr and json.loads(defout)['status']=='PLAN_ONLY',defrow
started=time.time_ns();child=subprocess.Popen(argv,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE);stdout,stderr=child.communicate();code=child.wait()
row={'name':'head1-outward-observation-plan-only','argv':argv,'pid':child.pid,'started_ns':started,'finished_ns':time.time_ns(),'exit_code':code,'wait_returncode':code,'reaped':True,'signals_sent':[]}
for suffix,raw in [('stdout',stdout),('stderr',stderr)]:
 with (phase/('head1-outward-observation-plan-only.'+suffix)).open('xb') as stream:stream.write(raw);stream.flush();os.fsync(stream.fileno())
 row[suffix+'_bytes']=len(raw);row[suffix+'_sha256']=hashlib.sha256(raw).hexdigest()
with (phase/'head1-outward-observation-plan-only.receipt.json').open('x') as stream:json.dump(row,stream,ensure_ascii=False,indent=2);stream.write('\n')
assert code==0 and not stderr,row
plan=m.strict_json(stdout.decode());assert plan['status']=='PLAN_ONLY' and plan['plan_sha256']==m.digest(plan['plan'])
p=plan['plan'];assert p['position_targets']==[['left',7,'head_motor_1']] and p['position_delta_raw']==24 and p['return_tolerance_raw']==4 and p['position_wait_ms']==800
assert p['head1_outward_observation']['wrapper']==reference and p['head1_outward_observation']['fixed_p']==16 and p['head1_outward_observation']['fixed_i']==0 and p['head1_outward_observation']['parameter_writes']==0 and p['head1_outward_observation']['ordinary_stop_wire']['additional_uart_reads']==0
assert p['head1_outward_observation']['readonly_stop_wire_helper']['path']==str(helper) and p['head1_outward_observation']['return_witness']=='UNMODIFIED_FROZEN_D97'
assert not output.exists() and not go.exists() and not record.exists()
post_start=time.time_ns();postchild=subprocess.Popen(['bash',str(base/'normal-read-r4/nonuart_probe_r4.sh')],stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE);postraw,posterr=postchild.communicate();postcode=postchild.wait()
postrow={'name':'post-nonuart','pid':postchild.pid,'argv':['bash',str(base/'normal-read-r4/nonuart_probe_r4.sh')],'started_ns':post_start,'finished_ns':time.time_ns(),'exit_code':postcode,'wait_returncode':postcode,'reaped':True,'signals_sent':[],'stdout_bytes':len(postraw),'stdout_sha256':hashlib.sha256(postraw).hexdigest(),'stderr_bytes':len(posterr),'stderr_sha256':hashlib.sha256(posterr).hexdigest()}
for suffix,raw in [('stdout',postraw),('stderr',posterr)]:
 with (phase/('post-nonuart.'+suffix)).open('xb') as stream:stream.write(raw);stream.flush();os.fsync(stream.fileno())
with (phase/'post-nonuart.receipt.json').open('x') as stream:json.dump(postrow,stream,ensure_ascii=False,indent=2);stream.write('\n')
assert postcode==0 and not posterr,postrow
post=json.loads(postraw);assert post['status']=='PASS_NON_UART_CURRENT_FACTS' and not post['errors'] and post['identity_before']['boot_id']==binding['host']['boot_id']
for side,ref in binding['usb'].items():assert all(post['devices'][side][k]==ref[k] for k in ('device','resolved','rdev','device_inode','link_inode'))
for side,files in binding['protection'].items():
 for name,ref in files.items():m.verify_protection_file(side,name,ref)
files=[]
for name in ('head1_outward_observation_r8.py','maintenance_bindings_head_settle_r8.json','default-plan-only.stdout','default-plan-only.stderr','default-plan-only.receipt.json','head1-outward-observation-plan-only.stdout','head1-outward-observation-plan-only.stderr','head1-outward-observation-plan-only.receipt.json','post-nonuart.stdout','post-nonuart.stderr','post-nonuart.receipt.json'):
 f=phase/name;raw=f.read_bytes();files.append({'name':name,'path':str(f),'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw),'base64':base64.b64encode(raw).decode()})
print(json.dumps({'status':'PASS_HEAD1_OUTWARD_OBSERVATION_R8_PREPARATION_ONLY','files':files,'candidate':reference,'original_binding_sha256':hashlib.sha256(old_raw).hexdigest(),'binding_change':'append one candidate ref only; every other dictionary/list unchanged','refs':len(binding['refs']),'plan_sha256':plan['plan_sha256'],'direct_children':3,'post_nonuart_status':post['status'],'post_nonuart_direct_children':len(post['commands']),'uart_operations':0,'go_created':False,'output_created':False,'launch_record_created':False,'hardware_started':False},ensure_ascii=False),flush=True)

PYREMOTE
